# EcoTech Balance 2 v1.0.2 pixel-accurate revision of the accepted design.
# Reuse all v1.0.1 resources and alter the 480px screen geometry only.
import runpy, json, zlib, base64
s = runpy.run_path('scripts/build_ecotech_v101.py')['source']
pairs=json.loads(zlib.decompress(base64.b64decode('')).decode('utf-8'))
for a,b in pairs:
    n=s.count(a)
    assert n==(2 if a=='pt((208,313,272,377))' else 1),(a,n)
    s=s.replace(a,b)
exec(compile(s,'ecotech_v102_source.py','exec'))
